function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'SQL' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with SQL(names, columns).';
  const [names, columns] = args[0];
  if (!Array.isArray(names) || !Array.isArray(columns)) return 'names and columns are arrays.';
  if (names.length < 1 || names.length > 10000) return 'There are 1 to 10^4 tables.';
  if (columns.length !== names.length) return 'names and columns need the same length.';
  const word = (s) => typeof s === 'string' && /^[a-z]{1,10}$/.test(s);
  if (!names.every(word)) return 'Table names are 1 to 10 lowercase letters.';
  if (new Set(names).size !== names.length) return 'Table names must be distinct.';
  if (!columns.every(c => Number.isInteger(c) && c >= 1 && c <= 10)) return 'Each table has 1 to 10 columns.';
  const id = (v) => Number.isInteger(v) && v >= -2147483648 && v <= 2147483647;
  let changes = 0;
  let selects = 0;
  let exports = 0;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a) || !word(a[0])) return 'Each call starts with a table name of 1 to 10 lowercase letters.';
    if (operations[i] === 'ins') {
      changes++;
      if (a.length !== 2 || !Array.isArray(a[1]) || a[1].length < 1 || a[1].length > 10) return 'ins needs a name and a row of 1 to 10 values.';
      if (!a[1].every(word)) return 'Row values are 1 to 10 lowercase letters.';
    } else if (operations[i] === 'rmv') {
      changes++;
      if (a.length !== 2 || !id(a[1])) return 'rmv needs a name and an integer rowId.';
    } else if (operations[i] === 'sel') {
      selects++;
      if (a.length !== 3 || !id(a[1]) || !id(a[2])) return 'sel needs a name, an integer rowId and an integer columnId.';
    } else if (operations[i] === 'exp') {
      exports++;
      if (a.length !== 1) return 'exp needs just a table name.';
    } else {
      return 'Only ins, rmv, sel and exp can follow the constructor.';
    }
  }
  if (changes > 2000) return 'At most 2000 calls to ins and rmv.';
  if (selects > 10000) return 'At most 10^4 calls to sel.';
  if (exports > 500) return 'At most 500 calls to exp.';
  return null;
}

