class SQL {
  constructor(names, columns) {
    this.tables = new Map();
    for (let i = 0; i < names.length; i++) {
      this.tables.set(names[i], { columns: columns[i], nextId: 1, rows: new Map() });
    }
  }

  ins(name, row) {
    const table = this.tables.get(name);
    if (!table || row.length !== table.columns) {
      return false;
    }
    table.rows.set(table.nextId, row);
    table.nextId++;
    return true;
  }

  rmv(name, rowId) {
    const table = this.tables.get(name);
    if (table) {
      table.rows.delete(rowId);
    }
  }

  sel(name, rowId, columnId) {
    const table = this.tables.get(name);
    const row = table ? table.rows.get(rowId) : undefined;
    if (!row || columnId < 1 || columnId > row.length) {
      return '<null>';
    }
    return row[columnId - 1];
  }

  exp(name) {
    const table = this.tables.get(name);
    if (!table) {
      return [];
    }
    const lines = [];
    for (const [id, row] of table.rows) {
      lines.push(id + ',' + row.join(','));
    }
    return lines;
  }
}

