class SQL {
  constructor(names, columns) {
    this.names = names.slice();
    this.columns = columns.slice();
    // Every successful insertion ever made, with a flag for deleted rows.
    this.history = [];
  }
  ins(name, row) {
    const index = this.names.indexOf(name);
    if (index === -1 || this.columns[index] !== row.length) return false;
    const id = this.history.filter(entry => entry.name === name).length + 1;
    this.history.push({ name, id, values: row.slice(), removed: false });
    return true;
  }
  rmv(name, rowId) {
    for (const entry of this.history) {
      if (entry.name === name && entry.id === rowId) entry.removed = true;
    }
  }
  sel(name, rowId, columnId) {
    const entry = this.history.find(e => e.name === name && e.id === rowId && !e.removed);
    if (entry === undefined || !(columnId >= 1 && columnId <= entry.values.length)) return '<null>';
    return entry.values[columnId - 1];
  }
  exp(name) {
    return this.history
      .filter(e => e.name === name && !e.removed)
      .sort((a, b) => a.id - b.id)
      .map(e => [String(e.id)].concat(e.values).join(','));
  }
}

