function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const word = (maxLength) => Array.from({ length: int(1, maxLength) }, () => letters[int(0, letters.length - 1)]).join('');
  const tableCount = large ? int(50, 300) : int(1, 3);
  const nameSet = new Set();
  for (let tries = 0; nameSet.size < tableCount && tries < 10000; tries++) nameSet.add(word(large ? 10 : 2));
  const names = [...nameSet];
  const columns = names.map(() => int(1, large ? 10 : 3));
  // A few busy tables get most of the calls so rows pile up, get removed and get exported.
  const busy = names.slice(0, Math.min(names.length, large ? 5 : 3));
  const pickName = () => {
    const roll = rand();
    if (roll < 0.1) return word(large ? 10 : 2); // may or may not be a real table
    if (roll < 0.8) return busy[int(0, busy.length - 1)];
    return names[int(0, names.length - 1)];
  };
  const nextId = new Map(names.map(name => [name, 1]));
  const width = new Map(names.map((name, i) => [name, columns[i]]));
  const operations = ['SQL'];
  const args = [[names, columns]];
  const calls = large ? 499 : int(1, 14);
  let exports = 0;
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    const name = pickName();
    const known = width.has(name);
    const issued = known ? nextId.get(name) - 1 : 3;
    if (roll < 0.4) {
      let length = known ? width.get(name) : int(1, 3);
      if (rand() < 0.15) length = Math.max(1, Math.min(10, length + (rand() < 0.5 ? -1 : 1)));
      const row = Array.from({ length }, () => word(large ? 10 : 3));
      if (known && length === width.get(name)) nextId.set(name, nextId.get(name) + 1);
      operations.push('ins');
      args.push([name, row]);
    } else if (roll < 0.6) {
      operations.push('rmv');
      args.push([name, int(1, issued + 1)]);
    } else if (roll < 0.92 || exports >= (large ? 40 : 14)) {
      const cols = known ? width.get(name) : 3;
      operations.push('sel');
      args.push([name, int(1, issued + 1), int(1, cols + 1)]);
    } else {
      exports++;
      operations.push('exp');
      args.push([name]);
    }
  }
  return [operations, args];
}
